  "description": "Illustrates the conservation status values and their meanings.",
  "definition": "Values range from 'Excellent' (recently conserved, no issues), 'Good' (stable with minor issues), 'Fair' (stable but with noticeable issues), 'Poor' (active deterioration), to 'Critical' (severe deterioration requiring immediate intervention)."
}

{
  "id": 20,
  "knowledge": "Organic Material Vulnerability",
  "description": "Identifies organic materials requiring special environmental conditions.",
  "definition": "Artifacts made of organic materials like 'Wood', 'Textile', or 'Paper' that also have a 'High' overall environmental sensitivity rating. These require specialized environmental controls."
}

{
  "id": 16,
  "knowledge": "Showcase Failure Risk",
  "description": "Identifies showcases at risk of failing to maintain proper environmental conditions.",
  "definition": "Occurs when a showcase's 'Showcase Environmental Stability Rating (SESR)' is less than 4 OR at least three maintenance indicators (e.g., seal condition, maintenance status, filter status) are in a critical state."
}

{
  "id": 56,
  "knowledge": "Conservation Priority Level",
  "description": "Classifies artifacts into priority levels based on their CPI scores.",
  "definition": "Based on the 'Conservation Priority Index (CPI)': 'High Priority' for scores > 7, 'Medium Priority' for scores between 4 and 7, and 'Low Priority' for scores <= 4."
}

{
  "id": 0,
  "knowledge": "Conservation Priority Index (CPI)",
  "description": "Calculates the overall conservation priority for an artifact based on multiple factors.",
  "definition": "Calculated as: ((Historical Significance Rating + Research Value Rating + Cultural Score) * (10 - Conservation Status Value)) / 30, where the conservation status is numerically mapped: Excellent=1, Good=3, Fair=5, Poor=7, Critical=10."
}

{
  "id": 2,
  "knowledge": "Environmental Risk Factor (ERF)",
  "description": "Quantifies the overall environmental risk to an artifact based on its sensitivities.",
  "definition": "Calculated as the average of an artifact's various environmental sensitivity scores. These scores are derived by converting qualitative ratings (e.g., 'Low', 'High') to numbers using 'Sensitivity Weight Values'."
}

{
  "id": 1,
  "knowledge": "Sensitivity Weight Values",
  "description": "Numerical weights for sensitivity calculations.",
  "definition": "A mapping of qualitative sensitivity ratings to numerical values for calculation purposes. For example: Low=1, Medium=5, High=10 for various environmental factors like light, temperature, and humidity."
}

{
  "id": 3,
  "knowledge": "Artifact Vulnerability Score (AVS)",
  "description": "Comprehensive score indicating how vulnerable an artifact is based on its conservation priority and environmental sensitivities.",
  "definition": "Calculated by multiplying the 'Conservation Priority Index (CPI)' by the 'Environmental Risk Factor (ERF)'. Higher scores indicate artifacts requiring more urgent attention."
}

{
  "id": 12,
  "knowledge": "Conservation Emergency",
  "description": "Identifies artifacts requiring immediate conservation intervention.",
  "definition": "A situation where an artifact's conservation status is 'Critical' AND its treatment priority is 'Urgent'."
}

{
  "id": 42,
  "knowledge": "High Deterioration Risk Artifact",
  "description": "Identifies artifacts at high risk of rapid deterioration due to environmental factors.",
  "definition": "An artifact that has a 'Total Environmental Threat Level (TETL)' greater than 15 AND falls under the 'Accelerated Deterioration Scenario'."
}

{
  "id": 31,
  "knowledge": "Total Environmental Threat Level (TETL)",
  "description": "Comprehensive measurement of all environmental threats to an artifact based on multiple risk factors.",
  "definition": "Calculated as: 'Environmental Risk Factor (ERF)' + 'Light Exposure Risk (LER)' + ('Material Deterioration Rate (MDR)' * 2)."
}

{
  "id": 26,
  "knowledge": "Showcase Airtightness Levels",
  "description": "Illustrates showcase airtightness measurement.",
  "definition": "A numerical value representing air changes per day. Museum-grade showcases typically have values below 0.1, while values up to 5.0 indicate poor airtightness."
}

{
  "id": 6,
  "knowledge": "Artifact Exhibition Compatibility (AEC)",
  "description": "Determines how compatible an artifact is with its current showcase environment.",
  "definition": "Calculated as: 10 - the absolute difference between the artifact's 'Environmental Risk Factor (ERF)' and the showcase's 'Showcase Environmental Stability Rating (SESR)'. A score closer to 10 indicates better compatibility."
}

{
  "id": 5,
  "knowledge": "Showcase Environmental Stability Rating (SESR)",
  "description": "Measures how well a showcase maintains stable environmental conditions.",
  "definition": "Calculated as: 10 - ((24-hour Temperature Variation + (24-hour Humidity Variation / 5) + Leak Rate) / 3). Higher scores indicate more stable showcases."
}

{
  "id": 7,
  "knowledge": "Material Deterioration Rate (MDR)",
  "description": "Estimates the rate of material deterioration based on environmental factors.",
  "definition": "Calculated as: (Artifact Age in Years * Environmental Risk Factor * (Relative Humidity - 50)^2 * Temperature in Celsius) / 100000. Higher values indicate faster deterioration."
}

